186	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
187		fs := newFlagSet("handoff", stderr)
188		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
189		request := fs.String("request", "", "交接请求号（用于去重）")
190		from := fs.String("from", "", "源站点")
191		to := fs.String("to", "", "目的站点")
192		var parcels stringList
193		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
194		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
195			return code
196		}
197	
198		cleanReq, err := cleanID("请求号", *request)
199		if err != nil {
200			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
201			return exitBusiness
202		}
203		cleanFrom, err := cleanID("源站点", *from)
204		if err != nil {
205			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
206			return exitBusiness
207		}
208		cleanTo, err := cleanID("目的站点", *to)
209		if err != nil {
210			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
211			return exitBusiness
212		}
213		if len(parcels) == 0 {
214			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
215			return exitBusiness
216		}
217		cleanParcels := make([]string, 0, len(parcels))
218		seen := make(map[string]bool, len(parcels))
219		for _, raw := range parcels {
220			id, err := cleanID("包裹编号", raw)
221			if err != nil {
222				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
223				return exitBusiness
224			}
225			if seen[id] {
226				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
227				return exitBusiness
228			}
229			seen[id] = true
230			cleanParcels = append(cleanParcels, id)
231		}
232		if cleanFrom == cleanTo {
233			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
234			return exitBusiness
235		}
236	
237		store, release, err := OpenForUpdate(dataFile)
238		if err != nil {
239			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
240			return exitBusiness
241		}
242		defer release()
243		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
244		if err != nil {
245			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
246			return exitBusiness
247		}
248	
249		headline := "交接成功"
250		if replayed {
251			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
252		}
253		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
254			headline, result.Request, result.From, result.To, len(result.Parcels))
255		for _, id := range result.Parcels {
256			fmt.Fprintf(stdout, "  - %s\n", id)
257		}
258		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
259		return exitOK
260	}
