313	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
314	// 不可为空、集合不可为空且编号不可重复。
315	func cleanParcelList(raw []string) ([]string, error) {
316		if len(raw) == 0 {
317			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
318		}
319		clean := make([]string, 0, len(raw))
320		seen := make(map[string]bool, len(raw))
321		for _, v := range raw {
322			id, err := cleanID("包裹编号", v)
323			if err != nil {
324				return nil, err
325			}
326			if seen[id] {
327				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
328			}
329			seen[id] = true
330			clean = append(clean, id)
331		}
332		return clean, nil
333	}
