393	func cmdReceipt(dataFile string, argv []string, stdout, stderr io.Writer) int {
394		fs := newFlagSet("receipt", stderr)
395		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
396		request := fs.String("request", "", "回执请求号（用于去重）")
397		batch := fs.String("batch", "", "配送批次号")
398		parcel := fs.String("parcel", "", "包裹编号")
399		result := fs.String("result", "", "回执结果：签收 或 失败")
400		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
401		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
402			return code
403		}
404	
405		cleanReq, err := cleanID("回执请求号", *request)
406		if err != nil {
407			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
408			return exitBusiness
409		}
410		cleanBatch, err := cleanID("批次号", *batch)
411		if err != nil {
412			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
413			return exitBusiness
414		}
415		cleanParcel, err := cleanID("包裹编号", *parcel)
416		if err != nil {
417			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
418			return exitBusiness
419		}
420		cleanResult, err := cleanID("回执结果", *result)
421		if err != nil {
422			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
423			return exitBusiness
424		}
425		if cleanResult != resultSigned && cleanResult != resultFailed {
426			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
427			return exitBusiness
428		}
429		cleanReason := strings.TrimSpace(*reason)
430		if cleanResult == resultFailed && cleanReason == "" {
431			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
432			return exitBusiness
433		}
434		if cleanResult == resultSigned && cleanReason != "" {
435			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
436			return exitBusiness
437		}
438	
439		store, release, err := OpenForUpdate(dataFile)
440		if err != nil {
441			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
442			return exitBusiness
443		}
444		defer release()
445		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
446		if err != nil {
447			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
448			return exitBusiness
449		}
450	
451		headline := "回执成功"
452		if replayed {
453			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
454			if res.RevokedBy != "" {
455				headline = "回执成功（请求号重复提交，返回首次保存的结果；该回执已撤销，未恢复回执或改变当前状态）"
