470	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
471	type receiptFileRecord struct {
472		Request string `json:"request"`
473		Batch   string `json:"batch"`
474		Parcel  string `json:"parcel"`
475		Result  string `json:"result"`
476		Reason  string `json:"reason"`
477	}
478	
479	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
480	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
481	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
482	// 都返回带记录位置的错误，整份不予导入。
483	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
484		raw, err := os.ReadFile(path)
485		if err != nil {
486			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
487		}
488		dec := json.NewDecoder(bytes.NewReader(raw))
489		dec.DisallowUnknownFields()
490		var records []receiptFileRecord
491		if err := dec.Decode(&records); err != nil {
492			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
493		}
494		var extra any
495		if err := dec.Decode(&extra); err != io.EOF {
496			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
497		}
498		if len(records) == 0 {
499			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
500		}
501	
502		clean := make([]ReceiptImportRecord, 0, len(records))
503		seen := make(map[string]bool, len(records))
504		for i, rawRec := range records {
505			rec, err := cleanReceiptImportRecord(rawRec)
506			if err != nil {
507				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
508			}
509			if seen[rec.Request] {
510				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
511			}
512			seen[rec.Request] = true
513			clean = append(clean, rec)
514		}
515		return clean, nil
516	}
517	
518	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
519	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
520	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
521		var rec ReceiptImportRecord
522		var err error
523		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
524			return rec, err
525		}
526		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
527			return rec, err
528		}
529		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
530			return rec, err
531		}
532		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
533			return rec, err
534		}
535		if rec.Result != resultSigned && rec.Result != resultFailed {
536			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
537		}
538		rec.Reason = strings.TrimSpace(raw.Reason)
539		if rec.Result == resultFailed && rec.Reason == "" {
540			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
541		}
542		if rec.Result == resultSigned && rec.Reason != "" {
543			return rec, fmt.Errorf("结果为签收时不可带原因")
544		}
545		return rec, nil
546	}
