548	func cmdReceiptImport(dataFile string, argv []string, stdout, stderr io.Writer) int {
549		fs := newFlagSet("receipt-import", stderr)
550		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
551		file := fs.String("file", "", "回执导入文件路径（JSON 数组，只读，不会被修改）")
552		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptImportHelp); !ok {
553			return code
554		}
555	
556		if strings.TrimSpace(*file) == "" {
557			fmt.Fprintf(stderr, "%s receipt-import: 选项 --file 需要一个非空的回执导入文件路径\n", appName)
558			return exitBusiness
559		}
560	
561		// 输入文件只读；读取、解析或清洗失败时整份不予导入。
562		records, err := loadReceiptImportFile(*file)
563		if err != nil {
564			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
565			return exitBusiness
566		}
567	
568		store, release, err := OpenForUpdate(dataFile)
569		if err != nil {
570			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
571			return exitBusiness
572		}
573		defer release()
574		items, err := store.ImportReceipts(records, now())
575		if err != nil {
576			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
577			return exitBusiness
578		}
579	
580		replayed := 0
581		for _, it := range items {
582			if it.Replayed {
583				replayed++
584			}
585		}
586		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
587		for i, it := range items {
588			mark := "新增"
589			if it.Replayed {
590				mark = "重放（返回首次保存的结果）"
591			}
592			if it.Revoked {
593				mark += "，该回执已撤销"
594			}
595			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
596				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
597			if it.Record.Result == resultFailed {
598				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
599			}
600			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
601		}
602		return exitOK
603	}
