652	func cmdBatch(dataFile string, argv []string, stdout, stderr io.Writer) int {
653		fs := newFlagSet("batch", stderr)
654		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
655		id := fs.String("id", "", "要查询的配送批次号")
656		if ok, code := parseFlags(fs, argv, stdout, stderr, printBatchHelp); !ok {
657			return code
658		}
659	
660		cleanIDVal, err := cleanID("批次号", *id)
661		if err != nil {
662			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
663			return exitBusiness
664		}
665	
666		store, err := Open(dataFile)
667		if err != nil {
668			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
669			return exitBusiness
670		}
671		b, err := store.BatchQuery(cleanIDVal)
672		if err != nil {
673			fmt.Fprintf(stderr, "%s batch: %v\n", appName, err)
674			return exitBusiness
675		}
676	
677		status := "配送中"
678		if b.Done() {
679			status = "已完成"
680		}
681		ab := store.BatchAbort(cleanIDVal)
682		if ab != nil {
683			status = "已中止"
684		}
685		tr := store.BatchTransferSource(cleanIDVal)
686		if tr != nil {
687			status = "已转交"
688		}
689		timeLabel := "出站时间"
690		if b.RelayedFrom != "" {
691			timeLabel = "接手时间"
692		}
693		fmt.Fprintf(stdout, "批次号: %s\n出发站: %s\n配送员: %s\n%s: %s\n批次状态: %s\n",
694			b.Batch, b.Station, b.Courier, timeLabel, b.Time.Format(timeFmt), status)
695		if b.RelayedFrom != "" {
696			src := store.TransferOf(b.RelayRequest)
697			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
698				b.RelayedFrom, src.FromCourier, b.RelayRequest)
699		}
700		if ab != nil {
701			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
702				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
703		}
704		if tr != nil {
705			fmt.Fprintf(stdout, "转交去向: 批次 %s（新配送员: %s）\n续接请求号: %s\n续接原因: %s\n转交时间: %s\n",
706				tr.ToBatch, tr.ToCourier, tr.Request, tr.Reason, tr.Time.Format(timeFmt))
707		}
708		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
709		for _, pid := range b.Parcels {
710			e, ok := b.Receipts[pid]
711			if !ok || e.RevokedBy != "" {
712				switch {
713				case tr != nil:
714					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    续接请求号: %s    时间: %s\n",
715						pid, tr.ToBatch, tr.Request, tr.Time.Format(timeFmt))
716				case ab != nil:
717					fmt.Fprintf(stdout, "  - %s    已收回    中止请求号: %s    原因: %s    时间: %s\n",
718						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
719				case ok:
720					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
721				default:
722					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
723				}
724				continue
725			}
726			if e.Result == resultFailed {
727				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
728					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
729			} else {
730				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
731					pid, e.Result, e.Request, e.Time.Format(timeFmt))
732			}
733		}
734		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
735			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
736			for _, rv := range rvs {
737				fmt.Fprintf(stdout, "  - 撤销请求号: %s    原回执请求号: %s    包裹: %s    批次: %s    原因: %s    时间: %s\n",
738					rv.Request, rv.Receipt, rv.Parcel, rv.Batch, rv.Reason, rv.Time.Format(timeFmt))
739			}
740		}
741		return exitOK
742	}
