36	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
37	type Event struct {
38		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执 | 发运 | 接收 | 改址
39		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站；发运时为源站，接收时为目的站；改址时为源站，包裹不移动）
40		Time       time.Time `json:"time"`                 // 发生时间
41		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销/接收/改址请求号（收件、出站、发运记录为空）
42		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）、发运/接收源站（仅发运、接收记录有）或改址前有效目的站（仅改址记录有）
43		To         string    `json:"to,omitempty"`         // 发运/接收目的站（仅发运、接收记录有）或改址后的新目的站（仅改址记录有）
44		Shipment   string    `json:"shipment,omitempty"`   // 运输单号（仅发运、接收、改址记录有）
45		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）、撤销原因（仅撤销回执记录有）或改址原因（仅改址记录有）
46		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
47		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
48		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
49		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
50		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
51		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
52		Incident string `json:"incident,omitempty"`
53		Note     string `json:"note,omitempty"`
54	}
55	
56	// Parcel 是一件包裹的台账信息。
57	type Parcel struct {
58		ID         string    `json:"id"`
59		Station    string    `json:"station"`    // 当前归属站点
60		Status     string    `json:"status"`     // 当前状态
61		Registered time.Time `json:"registered"` // 收件时间
62		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
63	}
64	
65	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
66	type HandoffResult struct {
67		Request    string    `json:"request"`
68		From       string    `json:"from"`
69		To         string    `json:"to"`
70		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
71		Time       time.Time `json:"time"`
72		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
73	}
74	
75	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
76	type ReturnResult struct {
77		Request string    `json:"request"` // 退回请求号
78		Handoff string    `json:"handoff"` // 被退回的原交接请求号
79		From    string    `json:"from"`    // 退回源站（原交接目的站）
80		To      string    `json:"to"`      // 退回目的站（原交接源站）
81		Reason  string    `json:"reason"`
82		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
83		Time    time.Time `json:"time"`
84	}
85	
86	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
87	// 台账级 Receipts 结果表与撤销记录共同保留）。
88	type ReceiptEntry struct {
89		Request string    `json:"request"`          // 回执请求号
90		Result  string    `json:"result"`           // 签收 | 失败
91		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
92		Time    time.Time `json:"time"`
93		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
94		RevokedBy string `json:"revokedBy,omitempty"`
95	}
96	
97	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
98	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
99	type BatchResult struct {
100		Batch    string                   `json:"batch"`
101		Station  string                   `json:"station"`  // 出发站
102		Courier  string                   `json:"courier"`  // 配送员
103		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
104		Time     time.Time                `json:"time"`     // 出站时间
105		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
106		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
107		AbortedBy string `json:"abortedBy,omitempty"`
108		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
109		// 转交永久生效，与中止互斥，批次不得复用。
110		TransferredBy string `json:"transferredBy,omitempty"`
111		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
112		// 与创建本批次的续接请求号（普通出站批次为空）。
113		RelayedFrom  string `json:"relayedFrom,omitempty"`
114		RelayRequest string `json:"relayRequest,omitempty"`
115	}
116	
117	// Effective 返回批次当前有效（未撤销）的回执数量。
118	func (b *BatchResult) Effective() int {
119		n := 0
120		for _, e := range b.Receipts {
121			if e != nil && e.RevokedBy == "" {
122				n++
123			}
124		}
125		return n
126	}
127	
128	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
129	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
130	
131	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
132	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
133	type ReceiptResult struct {
134		Request string    `json:"request"` // 回执请求号
135		Batch   string    `json:"batch"`   // 所属配送批次号
136		Parcel  string    `json:"parcel"`  // 包裹编号
137		Result  string    `json:"result"`  // 签收 | 失败
138		Reason  string    `json:"reason,omitempty"`
139		Time    time.Time `json:"time"`
140		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
141		RevokedBy string `json:"revokedBy,omitempty"`
142	}
143	
144	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
145	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
146	type FreezeResult struct {
147		Incident string    `json:"incident"` // 异常单号
148		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
149		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
150		Reason   string    `json:"reason"`   // 清理后的冻结原因
151		Time     time.Time `json:"time"`     // 冻结时间
152		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
153		ReleasedBy string `json:"releasedBy,omitempty"`
154	}
155	
156	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
157	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
158	type UnfreezeResult struct {
159		Request  string    `json:"request"`  // 解除请求号
160		Incident string    `json:"incident"` // 被解除的异常单号
161		Parcel   string    `json:"parcel"`   // 对应包裹编号
162		Note     string    `json:"note"`     // 清理后的处理说明
163		Time     time.Time `json:"time"`     // 解除时间
164	}
165	
166	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
167	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
168	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
169	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
170	type AbortResult struct {
171		Request string    `json:"request"` // 中止请求号
172		Batch   string    `json:"batch"`   // 被中止的配送批次号
173		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
174		Reason  string    `json:"reason"`  // 清理后的中止原因
175		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
176		Time    time.Time `json:"time"`    // 中止时间
177	}
178	
179	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
180	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
181	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
182	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
183	// 业务编号同名；失败的首次续接不占用请求号。
184	type TransferResult struct {
185		Request     string    `json:"request"`     // 续接请求号
186		FromBatch   string    `json:"fromBatch"`   // 原批次号
187		ToBatch     string    `json:"toBatch"`     // 新批次号
188		Station     string    `json:"station"`     // 出发站（沿用原批次）
189		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
190		ToCourier   string    `json:"toCourier"`   // 新配送员
191		Reason      string    `json:"reason"`      // 清理后的续接原因
192		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
193		Time        time.Time `json:"time"`        // 接手时间
194	}
195	
196	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
197	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
198	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
199	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
200	// 失败的首次撤销不占用请求号。
201	type RevokeResult struct {
202		Request string    `json:"request"` // 撤销请求号
203		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
204		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
205		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
206		Reason  string    `json:"reason"`  // 清理后的撤销原因
207		Time    time.Time `json:"time"`    // 撤销时间
208	}
209	
210	// ShipmentResult 记录一次成功的站间发运，用于运输单号去重、结果重放与运输单查询。
211	// 发运表示整单包裹已离开源站、尚未到达目的站：整单转为“站间在途”，归属站点暂记
212	// 源站，成员按首次提交顺序保存，保存后不可修改。运输单号独立于已有各类编号，
213	// 接收后也不释放；失败的首次发运不占用运输单号。
214	type ShipmentResult struct {
215		Shipment string    `json:"shipment"` // 运输单号
216		From     string    `json:"from"`     // 源站
217		To       string    `json:"to"`       // 目的站
218		Parcels  []string  `json:"parcels"`  // 成员，按首次提交顺序
219		Time     time.Time `json:"time"`     // 发运时间
220		// ReceivedBy 为使该运输单达到全部接收的接收请求号（尚未全部接收为空）；
221		// 全部接收永久生效，运输单号不释放。分批到站时可能经历多次接收，
222		// 每次接收记录于接收结果表，是否全部接收按各次接收事实统计。
223		ReceivedBy string `json:"receivedBy,omitempty"`
224		// Reroutes 为该运输单各次改址的改址请求号，按提交顺序追加（未改址为空）。
225		// 改址只变更当时全部未收件的有效目的站：原目的站、成员、发运结果与已有
226		// 接收事实永久保留。旧版数据文件没有该字段，按未改址处理。
227		Reroutes []string `json:"reroutes,omitempty"`
228	}
229	
230	// ReceiveResult 记录一次成功的到站接收，用于接收请求号去重与结果重放。
231	// 接收表示运输单的一批成员已到达目的站：按发运保存顺序将本次成员改归目的站、
232	// 恢复在站；全部成员到齐后运输单永久标记为已接收。接收请求号与运输单号及已有
233	// 各类编号分属独立去重范围，允许同名；失败的首次接收不占用请求号。
234	type ReceiveResult struct {
235		Request  string    `json:"request"`  // 接收请求号
236		Shipment string    `json:"shipment"` // 被接收的运输单号
237		Station  string    `json:"station"`  // 接收站点（即运输单目的站）
238		Parcels  []string  `json:"parcels"`  // 本次接收的成员，按发运保存顺序
239		Time     time.Time `json:"time"`     // 接收时间
240		// Explicit 为 true 表示本次接收显式选择了包裹集合；false 表示不选成员、
241		// 接收当时全部尚未接收件（旧版整单接收记录没有该字段，按不选成员处理）。
242		Explicit bool `json:"explicit,omitempty"`
243	}
244	
245	// RerouteResult 记录一次成功的运输途中改址，用于改址请求号去重与结果重放。
246	// 改址表示一张运输单当前全部未收件改送另一目的站：不另建运输单、不重新发运，
247	// 成员仍归源站、保持站间在途及作业限制，只变更余件的有效目的站；原成员、发运
248	// 结果、已有接收事实与轨迹永久保留。集合为受理时全部未收件，按发运保存顺序。
249	// 改址请求号独立去重，可与运输单号及其他业务编号同名；失败的首次改址不占用请求号。
250	type RerouteResult struct {
251		Request  string    `json:"request"`  // 改址请求号
252		Shipment string    `json:"shipment"` // 被改址的运输单号
253		From     string    `json:"from"`     // 改址前的有效目的站（首次为运输单原目的站）
254		To       string    `json:"to"`       // 新目的站（不同于改址前有效目的站与源站）
255		Reason   string    `json:"reason"`   // 清理后的改址原因
256		Parcels  []string  `json:"parcels"`  // 受理时全部未收件，按发运保存顺序
257		Time     time.Time `json:"time"`     // 改址时间
258	}
259	
260	// ledgerFile 是本地数据文件的磁盘结构。
261	type ledgerFile struct {
262		Version   int                        `json:"version"`
263		Parcels   map[string]*Parcel         `json:"parcels"`
264		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
265		Returns   map[string]*ReturnResult   `json:"returns"`
266		Batches   map[string]*BatchResult    `json:"batches"`
267		Receipts  map[string]*ReceiptResult  `json:"receipts"`
268		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
269		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
270		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
271		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
272		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
273		Shipments map[string]*ShipmentResult `json:"shipments"` // 以运输单号为键（含已接收的运输单，永久保留）
274		Receives  map[string]*ReceiveResult  `json:"receives"`  // 以接收请求号为键
275		Reroutes  map[string]*RerouteResult  `json:"reroutes"`  // 以改址请求号为键
276	}
277	
278	// Store 是一个数据文件对应的包裹站点交接台账。
279	type Store struct {
280		path string
281		data ledgerFile
282	}
283	
284	var (
285		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
286		ErrCorrupt = errors.New("数据文件已损坏")
287		// ErrNotFound 表示包裹编号在台账中不存在。
288		ErrNotFound = errors.New("包裹不存在")
289	)
290	
291	// Open 打开（或在文件不存在时建立）一个本地台账。
292	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
293	func Open(path string) (*Store, error) {
294		s := &Store{path: path}
295		raw, err := os.ReadFile(path)
296		if err != nil {
297			if os.IsNotExist(err) {
298				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
299					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
300					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
301					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}, Shipments: map[string]*ShipmentResult{},
302					Receives: map[string]*ReceiveResult{}, Reroutes: map[string]*RerouteResult{}}
303				return s, nil
304			}
305			return nil, fmt.Errorf("读取数据文件失败: %w", err)
306		}
307		if len(bytes.TrimSpace(raw)) == 0 {
308			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
309		}
310		if err := json.Unmarshal(raw, &s.data); err != nil {
311			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
312		}
313		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
314			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
315		}
316		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
317		if s.data.Returns == nil {
318			s.data.Returns = map[string]*ReturnResult{}
319		}
320		if s.data.Batches == nil {
321			s.data.Batches = map[string]*BatchResult{}
322		}
323		if s.data.Receipts == nil {
324			s.data.Receipts = map[string]*ReceiptResult{}
325		}
326		if s.data.Freezes == nil {
327			s.data.Freezes = map[string]*FreezeResult{}
328		}
329		if s.data.Unfreezes == nil {
330			s.data.Unfreezes = map[string]*UnfreezeResult{}
331		}
332		if s.data.Aborts == nil {
333			s.data.Aborts = map[string]*AbortResult{}
334		}
335		if s.data.Transfers == nil {
336			s.data.Transfers = map[string]*TransferResult{}
337		}
338		if s.data.Revokes == nil {
339			s.data.Revokes = map[string]*RevokeResult{}
340		}
341		// 早期版本的数据文件没有 shipments/receives 字段：按空表处理，无需手工修改。
342		if s.data.Shipments == nil {
343			s.data.Shipments = map[string]*ShipmentResult{}
344		}
345		if s.data.Receives == nil {
346			s.data.Receives = map[string]*ReceiveResult{}
347		}
348		// 早期版本的数据文件没有 reroutes 字段：按空表处理（各运输单均未改址），无需手工修改。
349		if s.data.Reroutes == nil {
350			s.data.Reroutes = map[string]*RerouteResult{}
351		}
352		for _, b := range s.data.Batches {
353			if b != nil && b.Receipts == nil {
354				b.Receipts = map[string]*ReceiptEntry{}
355			}
356		}
357		if err := s.data.validate(); err != nil {
358			return nil, err
359		}
360		return s, nil
361	}
362	
363	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
364	func (l *ledgerFile) validate() error {
365		for id, p := range l.Parcels {
366			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
367				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
368			}
369			switch p.Status {
370			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
371			default:
372				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
373			}
374			for i, e := range p.Trail {
375				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
376					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
377				}
378				if e.Op == "退回" {
379					if e.Request == "" || e.Reason == "" || e.From == "" {
380						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
381					}
382					if _, ok := l.Handoffs[e.RefRequest]; !ok {
383						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
384					}
385				}
386				if e.Op == "出站" {
387					if e.Batch == "" || e.Courier == "" {
388						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
389					}
390					if _, ok := l.Batches[e.Batch]; !ok {
391						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
392					}
393				}
394				if e.Op == "回执" {
395					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
396						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
397					}
398					if e.Result == resultFailed && e.Reason == "" {
399						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
400					}

