1282	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
1283	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
1284	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
1285	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
1286	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
1287	// 无需人工删除协调文件即可继续作业。
1288	func OpenForUpdate(path string) (s *Store, release func(), err error) {
1289		lockPath, err := coordinationPath(path)
1290		if err != nil {
1291			return nil, nil, err
1292		}
1293		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
1294			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
1295		}
1296		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
1297		if err != nil {
1298			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
1299		}

