1608	// Receipt 提交一件包裹在某个配送批次下的回执。
1609	//
1610	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1611	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1612	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1613	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1614	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1615	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1616	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1617	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1618	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1619	// 失败的首次回执不占用请求号。
1620	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1621		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1622		if err != nil || replayed {
1623			return res, replayed, err
1624		}
1625		if err := s.save(); err != nil {
1626			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1627			return nil, false, err
1628		}
1629		return res, false, nil
1630	}
1631	
1632	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1633	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1634	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1635	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1636		if saved, ok := s.data.Receipts[request]; ok {
1637			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1638				return saved, true, nil, nil
1639			}
1640			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1641				request, saved.Batch, saved.Parcel, saved.Result)
1642		}
1643	
1644		b, ok := s.data.Batches[batch]
1645		if !ok {
1646			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1647		}
1648		member := false
1649		for _, id := range b.Parcels {
1650			if id == parcel {
1651				member = true
1652				break
1653			}
1654		}
1655		if !member {
1656			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1657		}
1658		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1659			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1660		}
1661		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1662		if p.Status != statusDelivering || currentBatch(p) != batch {
1663			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1664		}
1665	
1666		res = &ReceiptResult{
1667			Request: request,
1668			Batch:   batch,
1669			Parcel:  parcel,
1670			Result:  result,
1671			Reason:  reason,
1672			Time:    now,
1673		}
1674		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1675	
1676		// 记录旧值，undo 在整体落盘失败时回滚。
1677		oldStatus, oldStation := p.Status, p.Station
1678		oldTrailLen := len(p.Trail)
1679		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1680	
1681		if result == resultSigned {
1682			p.Status = statusSigned // 站点保留不变
1683		} else {
1684			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1685			p.Station = b.Station
1686		}
1687		p.Trail = append(p.Trail, Event{
1688			Op:      "回执",
1689			Station: p.Station,
1690			Batch:   batch,
1691			Result:  result,
1692			Reason:  reason,
1693			Request: request,
1694			Time:    now,
1695		})
1696		b.Receipts[parcel] = entry
1697		s.data.Receipts[request] = res
1698	
1699		undo = func() {
1700			delete(s.data.Receipts, request)
1701			if hadEntry {
1702				b.Receipts[parcel] = oldEntry
1703			} else {
1704				delete(b.Receipts, parcel)
1705			}
1706			p.Status, p.Station = oldStatus, oldStation
1707			p.Trail = p.Trail[:oldTrailLen]
1708		}
1709		return res, false, undo, nil
1710	}
