1729	// ImportReceipts 按文件顺序整批应用回执记录。
1730	//
1731	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1732	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1733	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1734	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1735	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1736	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1737	// 全部为历史重放时不改写台账。
1738	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1739		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1740		work, err := s.fork()
1741		if err != nil {
1742			return nil, err
1743		}
1744		items := make([]ReceiptImportItem, 0, len(records))
1745		hasNew := false
1746		for i, rec := range records {
1747			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1748			if err != nil {
1749				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1750			}
1751			if !replayed {
1752				hasNew = true
1753			}
1754			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
1755		}
1756		if !hasNew {
1757			return items, nil // 全部为历史重放：不改写台账
1758		}
1759	
1760		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1761		orig := s.data
1762		s.data = work.data
1763		if err := s.save(); err != nil {
1764			s.data = orig
1765			return nil, err
1766		}
1767		return items, nil
1768	}
