1770	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1771	func (s *Store) fork() (*Store, error) {
1772		buf, err := json.Marshal(s.data)
1773		if err != nil {
1774			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1775		}
1776		var cp ledgerFile
1777		if err := json.Unmarshal(buf, &cp); err != nil {
1778			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1779		}
1780		return &Store{path: s.path, data: cp}, nil
1781	}
