1783	// RevokeReceipt 撤销一条误录的配送回执：经核实包裹实际仍由原配送员配送，
1784	// 撤销错误的签收或失败登记，不收回实物。包裹与批次取自原回执，不可另选。
1785	//
1786	// 首次撤销：原回执必须存在、未撤销且仍为该件在该批次的有效回执；所属批次
1787	// 未中止、未转交；原回执必须是该包裹最后一条轨迹（其后发生过流转、冻结或
1788	// 解除均拒绝，其他成员的后续操作不阻止撤销），包裹仍在原出发站且状态与回执
1789	// 结果一致。任一不满足则拒绝，不作任何改动。成功后该件恢复原批次配送中，
1790	// 站点、配送员不变，该回执不再计入有效回执（原本已完成的批次恢复配送中，
1791	// 原成员顺序与出站或接手时间保留，其他成员及回执不变）；原回执结果与轨迹
1792	// 永久保留并标记已撤销，追加一条撤销回执记录，回执请求号不删除也不释放。
1793	// 每件同批次最多一条未撤销回执，撤销后可用新回执请求号再次提交签收或失败，
1794	// 也可随原批次中止或续接。撤销不恢复配送前旧交接的退回资格。
1795	// 撤销请求号独立去重，可与其他业务编号同名：相同请求号且原回执、清理后的
1796	// 原因相同，直接返回首次撤销信息和时间，replayed 为 true，不检查现状、不
1797	// 再次改变进度或改写台账（后续重新回执、中止或续接后仍成立）；请求号相同
1798	// 但内容不同报冲突。每条原回执只能撤销一次，换撤销号再次撤销它拒绝；
1799	// 失败的首次撤销不占用请求号。
1800	func (s *Store) RevokeReceipt(request, receiptReq, reason string, now time.Time) (res *RevokeResult, replayed bool, err error) {
1801		if saved, ok := s.data.Revokes[request]; ok {
1802			if saved.Receipt == receiptReq && saved.Reason == reason {
1803				return saved, true, nil
1804			}
1805			return nil, false, fmt.Errorf("撤销请求号 %q 已用于一次不同的撤销（原回执=%q 原因=%q），内容冲突",
1806				request, saved.Receipt, saved.Reason)
1807		}
1808	
1809		rc, ok := s.data.Receipts[receiptReq]
1810		if !ok {
1811			return nil, false, fmt.Errorf("撤销失败：原回执请求号 %q 不存在", receiptReq)
1812		}
1813		if rc.RevokedBy != "" {
1814			return nil, false, fmt.Errorf("撤销失败：原回执 %q 已撤销（撤销请求号 %q），每条原回执只能撤销一次", receiptReq, rc.RevokedBy)
1815		}
1816		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
1817		if b.AbortedBy != "" {
1818			return nil, false, fmt.Errorf("撤销失败：批次 %q 已中止（中止请求号 %q），不能撤销其中的回执", rc.Batch, b.AbortedBy)
1819		}
1820		if b.TransferredBy != "" {
1821			return nil, false, fmt.Errorf("撤销失败：批次 %q 已转交（续接请求号 %q），不能撤销其中的回执", rc.Batch, b.TransferredBy)
1822		}
1823		entry := b.Receipts[rc.Parcel]
1824		if entry == nil || entry.Request != receiptReq {
1825			return nil, false, fmt.Errorf("撤销失败：回执 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
1826		}
1827		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
1828		last := p.Trail[len(p.Trail)-1]
1829		if last.Op != "回执" || last.Request != receiptReq {
1830			return nil, false, fmt.Errorf("撤销失败：包裹 %q 在原回执 %q 之后又发生流转、冻结或解除，不能撤销该回执", rc.Parcel, receiptReq)
1831		}
1832		if p.Station != b.Station {
1833			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能撤销该回执", rc.Parcel, p.Station, b.Station)
1834		}
1835		want := statusSigned
1836		if rc.Result == resultFailed {
1837			want = statusInStation
1838		}
1839		if p.Status != want {
1840			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前状态为 %q，与原回执 %q 的结果 %q 不一致，不能撤销",
1841				rc.Parcel, p.Status, receiptReq, rc.Result)
1842		}
1843	
1844		res = &RevokeResult{
1845			Request: request,
1846			Receipt: receiptReq,
1847			Batch:   rc.Batch,
1848			Parcel:  rc.Parcel,
1849			Reason:  reason,
1850			Time:    now,
1851		}
1852		s.data.Revokes[request] = res
1853		rc.RevokedBy = request
1854		entry.RevokedBy = request
1855	
1856		// 记录旧值，落盘失败时整体回滚。
1857		oldStatus := p.Status
1858		oldTrailLen := len(p.Trail)
1859		p.Status = statusDelivering // 恢复原批次配送中，站点与配送员不变
1860		p.Trail = append(p.Trail, Event{
1861			Op:         "撤销回执",
1862			Station:    b.Station,
1863			Batch:      rc.Batch,
1864			Request:    request,
1865			RefRequest: receiptReq,
1866			Reason:     reason,
1867			Time:       now,
1868		})
1869	
1870		if err := s.save(); err != nil {
1871			delete(s.data.Revokes, request)
1872			rc.RevokedBy = ""
1873			entry.RevokedBy = ""
1874			p.Status = oldStatus
1875			p.Trail = p.Trail[:oldTrailLen]
1876			return nil, false, err
1877		}
1878		return res, false, nil
1879	}
