1891	// BatchRevokes 返回一个配送批次相关的全部撤销记录，按撤销时间升序。
1892	func (s *Store) BatchRevokes(batch string) []*RevokeResult {
1893		var out []*RevokeResult
1894		for _, rv := range s.data.Revokes {
1895			if rv.Batch == batch {
1896				out = append(out, rv)
1897			}
1898		}
1899		sort.Slice(out, func(i, j int) bool { return out[i].Time.Before(out[j].Time) })
1900		return out
1901	}
