1903	// Freeze 对一件在站包裹登记异常冻结。
1904	//
1905	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1906	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1907	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1908	// 冻结只是管理记录，不移动实物、不算新流转。
1909	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1910	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1911	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1912	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1913	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1914		if saved, ok := s.data.Freezes[incident]; ok {
1915			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1916				return saved, true, nil
1917			}
1918			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1919				incident, saved.Parcel, saved.Station, saved.Reason)
1920		}
1921	
1922		p, ok := s.data.Parcels[parcel]
1923		if !ok {
1924			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1925		}
1926		if p.Station != station {
1927			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1928		}
1929		if p.Status != statusInStation {
1930			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1931		}
1932	
1933		res = &FreezeResult{
1934			Incident: incident,
1935			Parcel:   parcel,
1936			Station:  station,
1937			Reason:   reason,
1938			Time:     now,
1939		}
1940		s.data.Freezes[incident] = res
1941	
1942		// 记录旧值，落盘失败时整体回滚。
1943		oldStatus := p.Status
1944		oldTrail := append([]Event(nil), p.Trail...)
1945		p.Status = statusFrozen // 站点不变
1946		p.Trail = append(p.Trail, Event{
1947			Op:       "冻结",
1948			Station:  station,
1949			Incident: incident,
1950			Reason:   reason,
1951			Time:     now,
1952		})
1953	
1954		if err := s.save(); err != nil {
1955			delete(s.data.Freezes, incident)
1956			p.Status, p.Trail = oldStatus, oldTrail
1957			return nil, false, err
1958		}
1959		return res, false, nil
1960	}
1961	
1962	// Unfreeze 解除一件包裹当前的异常冻结。
1963	//
1964	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1965	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1966	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1967	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1968	// 解除只是管理记录，不移动实物、不算新流转。
1969	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1970	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1971	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1972	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1973		if saved, ok := s.data.Unfreezes[request]; ok {
1974			if saved.Incident == incident && saved.Note == note {
1975				return saved, true, nil
1976			}
1977			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1978				request, saved.Incident, saved.Note)
1979		}
1980	
1981		f, ok := s.data.Freezes[incident]
1982		if !ok {
1983			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1984		}
1985		if f.ReleasedBy != "" {
1986			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1987		}
1988		p, ok := s.data.Parcels[f.Parcel]
1989		if !ok {
1990			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1991		}
1992		if p.Status != statusFrozen || activeFreeze(p) != incident {
1993			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1994				incident, f.Parcel, activeFreeze(p))
1995		}
1996	
1997		res = &UnfreezeResult{
1998			Request:  request,
1999			Incident: incident,
2000			Parcel:   f.Parcel,
2001			Note:     note,
2002			Time:     now,
2003		}
2004		s.data.Unfreezes[request] = res
2005		f.ReleasedBy = request
2006	
2007		// 记录旧值，落盘失败时整体回滚。
2008		oldStatus := p.Status
2009		oldTrail := append([]Event(nil), p.Trail...)
2010		p.Status = statusInStation // 在原站恢复在站，站点不变
2011		p.Trail = append(p.Trail, Event{
2012			Op:       "解除冻结",
2013			Station:  f.Station,
2014			Incident: incident,
2015			Request:  request,
2016			Note:     note,
2017			Time:     now,
2018		})
2019	
2020		if err := s.save(); err != nil {
2021			delete(s.data.Unfreezes, request)
2022			f.ReleasedBy = ""
2023			p.Status, p.Trail = oldStatus, oldTrail
2024			return nil, false, err
2025		}
2026		return res, false, nil
2027	}
2028	
2029	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
2030	// 成员与站点取自原批次结果，不允许另选成员或站点。
2031	//
2032	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
2033	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
2034	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
2035	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），

