2351	// 首次接收：运输单必须存在，接收站点必须等于运输单当前有效目的站（原目的站
2352	// 应用已有各次改址后），本次至少接收一件。显式集合的每件选中件都必须属于原单、
2353	// 尚未接收，且仍在源站归该单在途；不选成员时本次集合为当时的全部尚未接收件。
2354	// 任一不满足则整次拒绝，不作任何改动。
2355	// 已收件不再检查接收条件也不变更，其后续交接、冻结、配送或再次发运不妨碍余件接收。
2356	// 成功时按发运保存顺序将本次成员改归有效目的站、恢复“在站”，各追加一条含运输单号、
2357	// 两站、接收请求号和时间的接收记录；全部成员到齐后运输单永久标记为已接收，
2358	// 随后可继续在站作业。接收算新的流转：接收后不能退回此前的旧交接。
2359	// 两种选择方式共用接收请求号去重范围，与运输单号及已有各类编号独立，允许同名：
2360	// 相同接收请求号且运输单、接收站点、选择方式相同（显式集合换序无关），直接返回
2361	// 首次接收集合与时间，replayed 为 true，不检查现状、不重算余件、不追加轨迹、
2362	// 不改写台账（全部接收及后续流转后仍成立）；请求号相同但运输单、接收站点、
2363	// 选择方式或显式集合不同报冲突；全部接收后新请求拒绝；失败的首次接收不占用请求号。
2364	func (s *Store) Receive(request, shipment, station string, parcels []string, now time.Time) (res *ReceiveResult, replayed bool, err error) {
2365		explicit := parcels != nil
2366		if saved, ok := s.data.Receives[request]; ok {
2367			if saved.Shipment == shipment && saved.Station == station && saved.Explicit == explicit &&
2368				(!explicit || sameSet(saved.Parcels, parcels)) {
2369				return saved, true, nil
2370			}
2371			return nil, false, fmt.Errorf("接收请求号 %q 已用于一次不同的接收（运输单=%q 接收站点=%q），内容冲突",
2372				request, saved.Shipment, saved.Station)
2373		}
2374	
2375		sh, ok := s.data.Shipments[shipment]
2376		if !ok {
2377			return nil, false, fmt.Errorf("接收失败：运输单号 %q 不存在", shipment)
2378		}
2379		eff := s.effectiveTo(sh)
2380		if station != eff {
2381			return nil, false, fmt.Errorf("接收失败：接收站点 %q 不是运输单 %q 的当前有效目的站 %q，本次接收未执行", station, shipment, eff)
2382		}
2383	
2384		received := s.receivedUnder(shipment)
2385		var members []string // 本次接收集合，按发运保存顺序
2386		if explicit {
2387			if len(parcels) == 0 {
2388				return nil, false, fmt.Errorf("接收失败：显式选择的包裹集合不可为空，本次接收未执行")
2389			}
2390			want := make(map[string]bool, len(parcels))
2391			for _, pid := range parcels {
2392				want[pid] = true
2393			}
2394			// 先做全部校验：选中件均属原单、尚未接收且仍归该单在途，任一不符整次拒绝。
2395			for _, pid := range parcels {
2396				member := false
2397				for _, mid := range sh.Parcels {
2398					if mid == pid {
2399						member = true
2400						break
2401					}
2402				}
2403				if !member {
2404					return nil, false, fmt.Errorf("接收失败：包裹 %q 不属于运输单 %q，本次接收未执行", pid, shipment)
2405				}
2406				if received[pid] {
2407					return nil, false, fmt.Errorf("接收失败：包裹 %q 已在运输单 %q 下接收，不能重复接收，本次接收未执行", pid, shipment)
2408				}
2409				p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2410				if p.Status != statusInTransit || p.Station != sh.From {
2411					return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，本次接收未执行",
2412						pid, p.Station, p.Status, shipment, sh.From)
2413				}
2414			}
2415			for _, mid := range sh.Parcels {
2416				if want[mid] {
2417					members = append(members, mid)
2418				}
2419			}
2420		} else {
2421			// 不选成员：本次集合为当时的全部尚未接收件，按发运保存顺序。
2422			for _, mid := range sh.Parcels {
2423				if !received[mid] {
2424					members = append(members, mid)
2425				}
2426			}
2427			if len(members) == 0 {
2428				return nil, false, fmt.Errorf("接收失败：运输单 %q 已全部接收（接收请求号 %q），没有尚未接收的成员，不能再次接收",
2429					shipment, sh.ReceivedBy)
2430			}
2431		}
2432	
2433		res = &ReceiveResult{
2434			Request:  request,
2435			Shipment: shipment,
2436			Station:  station,
2437			Parcels:  members,
2438			Time:     now,
2439			Explicit: explicit,
2440		}
2441		s.data.Receives[request] = res
2442		oldReceivedBy := sh.ReceivedBy
2443		if len(received)+len(members) == len(sh.Parcels) {
2444			sh.ReceivedBy = request // 全部成员到齐：运输单永久标记为已接收
2445		}
2446	
2447		// 记录旧值，落盘失败时整体回滚。
2448		prev := make(map[string]struct {
2449			station string
2450			status  string
2451			trail   []Event
2452		}, len(members))
2453		for _, pid := range members {
2454			p := s.data.Parcels[pid]
2455			prev[pid] = struct {
2456				station string
2457				status  string
2458				trail   []Event
2459			}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
2460			p.Station = eff
2461			p.Status = statusInStation
2462			p.Trail = append(p.Trail, Event{
2463				Op:       "接收",
2464				Station:  eff,
2465				From:     sh.From,
2466				To:       eff,
2467				Shipment: shipment,
2468				Request:  request,
2469				Time:     now,
2470			})
2471		}
2472	
2473		if err := s.save(); err != nil {
2474			delete(s.data.Receives, request)
2475			sh.ReceivedBy = oldReceivedBy
2476			for pid, old := range prev {
2477				p := s.data.Parcels[pid]
2478				p.Station, p.Status = old.station, old.status
2479				p.Trail = old.trail
2480			}
2481			return nil, false, err
2482		}
2483		return res, false, nil
2484	}
2485	
2486	// Reroute 提交一次运输途中改址：将一张运输单当前全部未收件改送另一目的站，
2487	// 不另建运输单、不重新发运。成员取自受理时的全部未收件，不允许另选。
2488	//
2489	// 首次受理：运输单必须存在且仍有未收件；预期当前目的站必须等于当前有效目的站
2490	// （原目的站应用已有各次改址后）；新目的站必须不同于当前有效目的站和源站。
2491	// 本次集合为受理时的全部未收件，每件都必须仍归该单在源站站间在途，任一不符
2492	// 整次拒绝、不作任何改动。已收件不参与受理条件检查也不变更，其后续合法作业
2493	// 不阻止改址。成功时按原发运顺序保存本次集合，成员仍归源站、保持站间在途及
2494	// 作业限制，只变更余件的有效目的站，逐件追加一条含请求号、运输单、前后目的站、
2495	// 原因和时间的改址轨迹；原成员、发运结果、已有接收事实与轨迹永久保留。
2496	// 改址可发生在发运与接收之间，允许再次改址（每次以当时余件为准），全部接收后
2497	// 拒绝新改址；改址不算到站、不恢复旧交接退回资格。
2498	// 改址请求号独立去重，可与运输单号及其他业务编号同名：相同请求号且运输单、
2499	// 预期当前目的站、新目的站、清理后的原因相同，直接返回首次改址信息、集合与
2500	// 时间，replayed 为 true，不检查现状、不重算余件、不改写台账（再次改址、接收
2501	// 和后续流转后仍成立）；请求号相同但内容不同报冲突；失败的首次改址不占用请求号。
2502	func (s *Store) Reroute(request, shipment, expect, to, reason string, now time.Time) (res *RerouteResult, replayed bool, err error) {
2503		if saved, ok := s.data.Reroutes[request]; ok {
2504			if saved.Shipment == shipment && saved.From == expect && saved.To == to && saved.Reason == reason {
2505				return saved, true, nil
2506			}
2507			return nil, false, fmt.Errorf("改址请求号 %q 已用于一次不同的改址（运输单=%q 新目的站=%q），内容冲突",
2508				request, saved.Shipment, saved.To)
2509		}
2510	
2511		sh, ok := s.data.Shipments[shipment]
2512		if !ok {
2513			return nil, false, fmt.Errorf("改址失败：运输单号 %q 不存在", shipment)
2514		}
2515		cur := s.effectiveTo(sh)
2516		if expect != cur {
2517			return nil, false, fmt.Errorf("改址失败：预期当前目的站 %q 与运输单 %q 当前有效目的站 %q 不符，整次改址未执行",
2518				expect, shipment, cur)
2519		}
2520		if to == cur {
2521			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与当前有效目的站相同，整次改址未执行", to)
2522		}
2523		if to == sh.From {
2524			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与运输单 %q 源站相同，整次改址未执行", to, shipment)
2525		}
2526	
2527		// 本次集合为受理时的全部未收件，按发运保存顺序。
2528		received := s.receivedUnder(shipment)
2529		members := make([]string, 0, len(sh.Parcels))
2530		for _, pid := range sh.Parcels {
2531			if !received[pid] {
2532				members = append(members, pid)
2533			}
2534		}
2535		if len(members) == 0 {
2536			return nil, false, fmt.Errorf("改址失败：运输单 %q 已全部接收（接收请求号 %q），没有未收件，不能改址", shipment, sh.ReceivedBy)
2537		}
2538	
2539		// 先做全部校验：每件未收件都必须仍归该单在源站站间在途，任一不符整次拒绝。
2540		for _, pid := range members {
2541			p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2542			if p.Status != statusInTransit || p.Station != sh.From {
2543				return nil, false, fmt.Errorf("改址失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，整次改址未执行",
2544					pid, p.Station, p.Status, shipment, sh.From)
2545			}
2546		}
2547	
2548		res = &RerouteResult{
2549			Request:  request,
2550			Shipment: shipment,
2551			From:     cur,
2552			To:       to,
2553			Reason:   reason,
2554			Parcels:  members,
2555			Time:     now,
2556		}
2557		s.data.Reroutes[request] = res
2558		sh.Reroutes = append(sh.Reroutes, request)
2559	
2560		// 记录旧值，落盘失败时整体回滚。包裹仍归源站、保持站间在途，只追加改址轨迹。
2561		prev := make(map[string][]Event, len(members))
2562		for _, pid := range members {
2563			p := s.data.Parcels[pid]
2564			prev[pid] = append([]Event(nil), p.Trail...)
2565			p.Trail = append(p.Trail, Event{
2566				Op:       "改址",
2567				Station:  sh.From,
2568				From:     cur,
2569				To:       to,
2570				Shipment: shipment,
2571				Request:  request,
2572				Reason:   reason,
2573				Time:     now,
2574			})
2575		}
2576	
2577		if err := s.save(); err != nil {
2578			delete(s.data.Reroutes, request)
2579			sh.Reroutes = sh.Reroutes[:len(sh.Reroutes)-1]
2580			for pid, old := range prev {
2581				s.data.Parcels[pid].Trail = old
2582			}
2583			return nil, false, err
2584		}
2585		return res, false, nil
2586	}
2587	
2588	// effectiveTo 返回运输单当前有效目的站：原目的站按保存顺序应用全部改址后的结果。
2589	// 载入校验保证改址列表引用的请求均存在且链式衔接，这里不做错误处理。
2590	func (s *Store) effectiveTo(sh *ShipmentResult) string {
2591		to := sh.To
2592		for _, req := range sh.Reroutes {
2593			if r := s.data.Reroutes[req]; r != nil {
2594				to = r.To
2595			}
2596		}
2597		return to
2598	}
2599	
2600	// RerouteOf 按改址请求号返回改址结果；不存在时返回 nil。
2601	func (s *Store) RerouteOf(request string) *RerouteResult {
2602		return s.data.Reroutes[request]
2603	}
