2605	// ShipmentReroutes 按提交顺序返回一张运输单的全部改址记录；运输单不存在或未改址时为空。
2606	func (s *Store) ShipmentReroutes(shipment string) []*RerouteResult {
2607		sh, ok := s.data.Shipments[shipment]
2608		if !ok {
2609			return nil
2610		}
2611		out := make([]*RerouteResult, 0, len(sh.Reroutes))
2612		for _, req := range sh.Reroutes {
2613			if r := s.data.Reroutes[req]; r != nil {
2614				out = append(out, r)
2615			}
2616		}
2617		return out
2618	}
