2620	// ShipmentQuery 按运输单号返回发运结果；运输单不存在时报错。
2621	func (s *Store) ShipmentQuery(shipment string) (*ShipmentResult, error) {
2622		sh, ok := s.data.Shipments[shipment]
2623		if !ok {
2624			return nil, fmt.Errorf("运输单 %q 不存在", shipment)
2625		}
2626		return sh, nil
