2634	// receivedUnder 返回一张运输单已接收成员的集合（按接收结果表统计）。
2635	func (s *Store) receivedUnder(shipment string) map[string]bool {
2636		got := make(map[string]bool)
2637		for _, r := range s.data.Receives {
2638			if r == nil || r.Shipment != shipment {
2639				continue
2640			}
2641			for _, pid := range r.Parcels {
2642				got[pid] = true
2643			}
2644		}
2645		return got
2646	}
