2648	// ShipmentReceiveOf 返回一件包裹在指定运输单下的接收结果；该件尚未接收时返回 nil。
2649	func (s *Store) ShipmentReceiveOf(shipment, parcel string) *ReceiveResult {
2650		for _, r := range s.data.Receives {
2651			if r == nil || r.Shipment != shipment {
2652				continue
2653			}
2654			for _, pid := range r.Parcels {
2655				if pid == parcel {
2656					return r
2657				}
2658			}
2659		}
2660		return nil
2661	}
2662	
2663	// ActiveShipment 返回包裹当前所属的运输单（该包裹是其中尚未接收的成员）；
2664	// 包裹不存在或不归某单在途时返回 nil。已收件即使原单未收齐也不再归属原单。
2665	func (s *Store) ActiveShipment(id string) *ShipmentResult {
2666		p, ok := s.data.Parcels[id]
2667		if !ok || p.Status != statusInTransit {
2668			return nil
2669		}
2670		for _, sh := range s.data.Shipments {
2671			if sh == nil {
2672				continue
2673			}
2674			member := false
2675			for _, pid := range sh.Parcels {
2676				if pid == id {
2677					member = true
2678					break
2679				}
2680			}
2681			if member && s.ShipmentReceiveOf(sh.Shipment, id) == nil {
2682				return sh
2683			}
2684		}
2685		return nil
2686	}
