2688	// currentBatch 返回包裹当前配送归属的批次号（最后一条出站或续接记录的批次）；
2689	// 不在配送中返回空。续接不新增出站记录，但会把当前配送归属切换到新批次。
2690	func currentBatch(p *Parcel) string {
2691		for i := len(p.Trail) - 1; i >= 0; i-- {
2692			if p.Trail[i].Op == "出站" || p.Trail[i].Op == "续接" {
2693				return p.Trail[i].Batch
2694			}
2695		}
2696		return ""
2697	}
2698	
2699	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
2700	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
2701	func activeFreeze(p *Parcel) string {
2702		if p.Status != statusFrozen {
2703			return ""
2704		}
2705		for i := len(p.Trail) - 1; i >= 0; i-- {
2706			if p.Trail[i].Op == "冻结" {
2707				return p.Trail[i].Incident
2708			}
2709		}
2710		return ""
2711	}
2712	
2713	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执/收回/续接/撤销回执/发运/接收）。
2714	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
2715	func lastFlowEvent(trail []Event) Event {
2716		for i := len(trail) - 1; i >= 0; i-- {
2717			switch trail[i].Op {
2718			case "冻结", "解除冻结":
2719				continue
2720			default:
2721				return trail[i]
2722			}
2723		}
2724		return Event{}
2725	}
