2736	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
2737	func sameOrder(a, b []string) bool {
2738		if len(a) != len(b) {
2739			return false
2740		}
2741		for i := range a {
2742			if a[i] != b[i] {
2743				return false
2744			}
2745		}
2746		return true
2747	}
2748	
2749	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
2750	func sameSet(a, b []string) bool {
2751		if len(a) != len(b) {
2752			return false
2753		}
2754		x := append([]string(nil), a...)
2755		y := append([]string(nil), b...)
2756		sort.Strings(x)
2757		sort.Strings(y)
2758		for i := range x {
2759			if x[i] != y[i] {
2760				return false
2761			}
2762		}
2763		return true
2764	}
2765	
2766	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
2767	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
2768	func (s *Store) save() error {
