335		// 篡改续接结果内容（新配送员不一致）也应判为损坏。
336		tampered = []byte(strings.Replace(string(raw), `"toCourier": "李四"`, `"toCourier": "王五"`, 1))
337		if err := os.WriteFile(path, tampered, 0o644); err != nil {
338			t.Fatal(err)
339		}
340		if _, err := Open(path); !errors.Is(err, ErrCorrupt) {
341			t.Fatalf("续接结果与轨迹不一致应拒绝读写: %v", err)
342		}
343	}
344

