11	)
12	
13	// mustReceiveParcels 以显式集合方式接收，要求首次受理成功。
14	func mustReceiveParcels(t *testing.T, s *Store, request, shipment, station string, parcels []string, now time.Time) *ReceiveResult {
15		t.Helper()
16		res, replayed, err := s.Receive(request, shipment, station, parcels, now)
17		if err != nil || replayed {
18			t.Fatalf("Receive(%q, %v) 意外失败: %v replayed=%v", request, parcels, err, replayed)
19		}
20		return res
21	}
22	
23	// 准备三件在站点A 在站的包裹 P001、P002、P003，并发运 S1（站点A -> 站点B）。
24	func setupPartialShip(t *testing.T, s *Store) time.Time {
25		t.Helper()
26		t1 := tClock(2026, 10, 5, 9, 0)
27		for _, id := range []string{"P001", "P002", "P003"} {
28			mustRegister(t, s, id, "站点A", t1)
29		}
30		shipTime := tClock(2026, 10, 5, 10, 0)
31		mustShip(t, s, "S1", "站点A", "站点B", []string{"P001", "P002", "P003"}, shipTime)
32		return shipTime
33	}
34	
35	// 分批接收：显式集合先到件入站作业，余件保持在途及作业限制；
36	// 已收件的后续交接、冻结不妨碍余件补齐；全部到齐后运输单标记已接收。
37	func TestReceivePartialExplicit(t *testing.T) {
38		s, _ := openTempStore(t)
39		setupPartialShip(t, s)
40	
41		recvTime := tClock(2026, 10, 5, 12, 0)
42		res := mustReceiveParcels(t, s, "RS1", "S1", "站点B", []string{"P003", "P001"}, recvTime)
43		if !res.Explicit {
44			t.Fatalf("显式集合接收应标记选择方式: %+v", res)
45		}
46		// 本次集合按原发运顺序保存，与提交顺序无关。
47		if !sameOrder(res.Parcels, []string{"P001", "P003"}) {
48			t.Fatalf("本次集合应按发运保存顺序: %v", res.Parcels)
49		}
50		sh, _ := s.ShipmentQuery("S1")
51		if sh.ReceivedBy != "" {
52			t.Fatalf("部分接收不应标记全部接收: %+v", sh)
53		}
54		// 已收件改归目的站、恢复在站，追加接收轨迹。
55		for _, id := range []string{"P001", "P003"} {
56			p, _ := s.Query(id)
57			if p.Status != statusInStation || p.Station != "站点B" {
58				t.Fatalf("已收件 %q 应归目的站在站: status=%q station=%q", id, p.Status, p.Station)
59			}
60			last := p.Trail[len(p.Trail)-1]
61			if last.Op != "接收" || last.Request != "RS1" || last.Shipment != "S1" ||
62				last.From != "站点A" || last.To != "站点B" || !last.Time.Equal(recvTime) {
63				t.Fatalf("已收件 %q 缺少接收轨迹: %+v", id, last)
64			}
65			if s.ActiveShipment(id) != nil {
66				t.Fatalf("已收件 %q 不应再归属原单在途", id)
67			}
68		}
69		// 未选余件保持源站在途及作业限制。
70		p2, _ := s.Query("P002")
71		if p2.Status != statusInTransit || p2.Station != "站点A" || len(p2.Trail) != 2 {
72			t.Fatalf("未选余件应保持源站在途: %+v", p2)
73		}
74		if sh := s.ActiveShipment("P002"); sh == nil || sh.Shipment != "S1" {
75			t.Fatalf("未选余件应仍归 S1 在途")
76		}
77		if _, _, err := s.Handoff("R1", "站点A", "站点C", []string{"P002"}, tClock(2026, 10, 5, 12, 30)); err == nil {
78			t.Fatalf("在途余件应不能交接")
79		}
80		if _, _, err := s.Dispatch("B1", "站点A", "张三", []string{"P002"}, tClock(2026, 10, 5, 12, 30)); err == nil {
81			t.Fatalf("在途余件应不能配送出站")
82		}
83		if _, _, err := s.Freeze("E1", "P002", "站点A", "异常", tClock(2026, 10, 5, 12, 30)); err == nil {
84			t.Fatalf("在途余件应不能冻结")
85		}
86	
87		// 已收件的后续交接、冻结、再次发运不妨碍余件接收。
88		mustHandoff(t, s, "R2", "站点B", "站点C", []string{"P001"}, tClock(2026, 10, 5, 13, 0))
89		mustFreeze(t, s, "E2", "P003", "站点B", "外包装破损", tClock(2026, 10, 5, 13, 0))
90		mustReceiveParcels(t, s, "RS2", "S1", "站点B", []string{"P002"}, tClock(2026, 10, 5, 14, 0))
91		sh, _ = s.ShipmentQuery("S1")
92		if sh.ReceivedBy != "RS2" {
93			t.Fatalf("全部到齐后运输单应标记完成接收的请求号: %+v", sh)
94		}
95		p2, _ = s.Query("P002")
96		if p2.Status != statusInStation || p2.Station != "站点B" {
97			t.Fatalf("余件补齐后应归目的站在站: %+v", p2)
98		}
99		// 全部接收后新请求拒绝（两种方式都拒绝），运输单号不释放。
100		if _, _, err := s.Receive("RS9", "S1", "站点B", nil, tClock(2026, 10, 5, 15, 0)); err == nil {
101			t.Fatalf("全部接收后不选成员的新请求应拒绝")
102		}
103		if _, _, err := s.Receive("RS10", "S1", "站点B", []string{"P002"}, tClock(2026, 10, 5, 15, 0)); err == nil {
104			t.Fatalf("全部接收后显式集合的新请求应拒绝")
105		}
106		if _, replayed, err := s.Ship("S1", "站点A", "站点B", []string{"P003", "P002", "P001"}, tClock(2026, 10, 5, 16, 0)); err != nil || !replayed {
107			t.Fatalf("全部接收后运输单号不释放，同内容发运应重放: %v replayed=%v", err, replayed)
108		}
109	}
110	
111	// 不选成员方式：首次受理时取当时余件；先显式接收一批后，不选成员接收剩余全部。
112	func TestReceiveRemainingWithoutSelection(t *testing.T) {
113		s, _ := openTempStore(t)
114		setupPartialShip(t, s)
115	
116		mustReceiveParcels(t, s, "RS1", "S1", "站点B", []string{"P002"}, tClock(2026, 10, 5, 12, 0))
117		recvTime := tClock(2026, 10, 5, 13, 0)
118		res := mustReceive(t, s, "RS2", "S1", "站点B", recvTime)
119		if res.Explicit {
120			t.Fatalf("不选成员接收不应标记显式方式: %+v", res)
121		}
122		// 本次集合为当时的余件（P001、P003），按发运保存顺序。
123		if !sameOrder(res.Parcels, []string{"P001", "P003"}) {
124			t.Fatalf("不选成员应取当时余件: %v", res.Parcels)
125		}
126		sh, _ := s.ShipmentQuery("S1")
127		if sh.ReceivedBy != "RS2" {
128			t.Fatalf("全部到齐后应标记完成接收: %+v", sh)
129		}
130		for _, id := range []string{"P001", "P003"} {
131			p, _ := s.Query(id)
132			if p.Status != statusInStation || p.Station != "站点B" {
133				t.Fatalf("余件 %q 应归目的站在站: %+v", id, p)
134			}
135		}
136	}
137	
138	// 重放：两种方式共用请求号范围；同号同方式同内容返回首次集合与时间，
139	// 不检查现状、不重算余件、不追加轨迹或改写文件；换集合或切换方式冲突。
140	func TestReceivePartialReplayAndConflict(t *testing.T) {
141		s, path := openTempStore(t)
142		setupPartialShip(t, s)
143		recvTime := tClock(2026, 10, 5, 12, 0)
144		mustReceiveParcels(t, s, "RS1", "S1", "站点B", []string{"P001", "P002"}, recvTime)
145		mustReceive(t, s, "RS2", "S1", "站点B", tClock(2026, 10, 5, 13, 0)) // 不选成员，收下 P003，全部到齐
146		// 全部接收及后续流转之后重放仍成立。
147		mustHandoff(t, s, "R9", "站点B", "站点C", []string{"P001"}, tClock(2026, 10, 5, 14, 0))
148		before, err := os.ReadFile(path)
149		if err != nil {
150			t.Fatal(err)
151		}
152	
153		// 显式集合换序无关：返回首次集合与时间。
154		res, replayed, err := s.Receive("RS1", "S1", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 5, 15, 0))
155		if err != nil || !replayed || !sameOrder(res.Parcels, []string{"P001", "P002"}) || !res.Time.Equal(recvTime) {
156			t.Fatalf("显式集合换序重放应返回首次集合与时间: %+v replayed=%v err=%v", res, replayed, err)
157		}
158		// 不选成员重放：返回首次集合（当时的余件），不检查现状、不重算余件。
159		res2, replayed, err := s.Receive("RS2", "S1", "站点B", nil, tClock(2026, 10, 5, 15, 0))
160		if err != nil || !replayed || !sameOrder(res2.Parcels, []string{"P003"}) {
161			t.Fatalf("不选成员重放应返回首次集合: %+v replayed=%v err=%v", res2, replayed, err)
162		}
163		// 重放不追加轨迹、不改写文件。
164		p1, _ := s.Query("P001")
165		if len(p1.Trail) != 4 { // 收件、发运、接收、交接
166			t.Fatalf("重放不应追加轨迹，得到 %d 条", len(p1.Trail))
167		}
168		after, err := os.ReadFile(path)
169		if err != nil {
170			t.Fatal(err)
171		}
172		if string(before) != string(after) {
173			t.Fatalf("重放不应改写数据文件")
174		}
175	
