379	// 并发接收：重叠成员至多一次生效，不重叠的合法接收全部保留。
380	func TestConcurrentReceiveOverlapping(t *testing.T) {
381		dbPath := filepath.Join(t.TempDir(), "ledger.json")
382		for _, id := range []string{"P001", "P002", "P003"} {
383			if _, _, code := runCLI(t, dbPath, "register", "--id", id, "--station", "站点A"); code != 0 {
384				t.Fatalf("登记 %s 失败", id)
385			}
386		}
387		if _, _, code := runCLI(t, dbPath, "ship", "--shipment", "S1", "--from", "站点A", "--to", "站点B",
388			"--parcel", "P001", "--parcel", "P002", "--parcel", "P003"); code != 0 {
389			t.Fatalf("发运失败")
390		}
391	
392		// 两个请求都包含 P002：至多一个生效。
393		_, _, codes := runParallel(t, 2, func(i int) []string {
394			if i == 0 {
395				return []string{"--data", dbPath, "receive", "--request", "RS1", "--shipment", "S1",
396					"--station", "站点B", "--parcel", "P001", "--parcel", "P002"}
397			}
398			return []string{"--data", dbPath, "receive", "--request", "RS2", "--shipment", "S1",
399				"--station", "站点B", "--parcel", "P002", "--parcel", "P003"}
400		})
401		if got := countCodes(codes, exitOK); got != 1 {
402			t.Fatalf("重叠成员的并发接收应至多一次生效，成功 %d 次（codes=%v）", got, codes)
403		}
404		s, err := Open(dbPath)
405		if err != nil {
406			t.Fatalf("打开台账失败: %v", err)
407		}
408		gotP002 := s.ShipmentReceiveOf("S1", "P002")
409		if gotP002 == nil {
410			t.Fatalf("P002 应被恰好一个请求接收")
411		}
412		other := "RS2"
413		if gotP002.Request == "RS2" {
414			other = "RS1"
415		}
416		if s.ReceiveOf(other) != nil {
417			t.Fatalf("失败的重叠接收不应占用请求号 %q", other)
418		}
419	
420		// 不重叠的合法并发接收全部保留。
421		_, _, codes = runParallel(t, 2, func(i int) []string {
422			if i == 0 {
423				return []string{"--data", dbPath, "receive", "--request", "RS3", "--shipment", "S1",
424					"--station", "站点B", "--parcel", "P001"}
425			}
426			return []string{"--data", dbPath, "receive", "--request", "RS4", "--shipment", "S1",
427				"--station", "站点B", "--parcel", "P003"}
428		})
429		// P001 或 P003 可能已在上一步被接收：只统计仍合法的请求。
430		s, err = Open(dbPath)
431		if err != nil {
432			t.Fatalf("打开台账失败: %v", err)
433		}
434		want := 0
435		if s.ShipmentReceiveOf("S1", "P001") == nil || s.ShipmentReceiveOf("S1", "P001").Request == "RS3" {
436			want++
437		}
438		if s.ShipmentReceiveOf("S1", "P003") == nil || s.ShipmentReceiveOf("S1", "P003").Request == "RS4" {
439			want++
440		}
441		if got := countCodes(codes, exitOK); got != want {
442			t.Fatalf("不重叠的合法接收应全部保留，应成功 %d 次，实际 %d 次（codes=%v）", want, got, codes)
443		}
444		s, err = Open(dbPath)
445		if err != nil {
446			t.Fatalf("打开台账失败: %v", err)
447		}
448		// 全部成员最终都被接收且运输单标记完成。
449		sh, _ := s.ShipmentQuery("S1")
450		if sh.ReceivedBy == "" {
451			t.Fatalf("全部接收后运输单应标记完成: %+v", sh)
452		}
453		for _, pid := range []string{"P001", "P002", "P003"} {
454			if s.ShipmentReceiveOf("S1", pid) == nil {
455				t.Fatalf("包裹 %q 应已被接收", pid)
456			}
457			p, _ := s.Query(pid)
458			if p.Station != "站点B" || p.Status != statusInStation {
459				t.Fatalf("包裹 %q 应归目的站在站: %+v", pid, p)
460			}
461		}
462	}
