542		buf, err := json.Marshal(m)
543		if err != nil {
544			t.Fatal(err)
545		}
546		if err := os.WriteFile(path, buf, 0o644); err != nil {
547			t.Fatal(err)
548		}
549		if _, err := Open(path); !errors.Is(err, ErrCorrupt) {
550			t.Fatalf("接收成员与轨迹矛盾应识别为数据损坏: %v", err)
551		}
