// TransferredOut 报告一件该批次成员是否已在某次续接中转交（当前不再由该批次配送）。
func (b *BatchResult) TransferredOut(pid string) bool {
	for _, req := range b.Transfers {
		if t := b.requestTransfer(req); t != nil {
			for _, id := range t.Parcels {
				if id == pid {
					return true
				}
			}
		}
	}
	return false
}

// openParcels 返回该批次当前仍由本批次配送的待配送成员（无有效回执且未转交），
// 按原成员顺序。
func (b *BatchResult) openParcels(ledger *ledgerFile) []string {
	out := make([]string, 0, len(b.Parcels))
	for _, pid := range b.Parcels {
		if e, done := b.Receipts[pid]; done && e.RevokedBy == "" {
			continue // 已有有效回执
		}
		transferred := false
		for _, req := range b.Transfers {
			if t := ledger.Transfers[req]; t != nil {
				for _, id := range t.Parcels {
					if id == pid {
						transferred = true
						break
					}
				}
			}
			if transferred {
				break
			}
		}
		if !transferred {
			out = append(out, pid)
		}
	}
	return out
}

