		FromBatch:   fromBatch,
		ToBatch:     toBatch,
		Station:     b.Station,
		FromCourier: b.Courier,
		ToCourier:   courier,
		Reason:      reason,
		Parcels:     append([]string(nil), moved...),
		Time:        now,
	}
	s.data.Transfers[request] = res
	s.data.Batches[toBatch] = &BatchResult{
		Batch:        toBatch,
		Station:      b.Station,
		Courier:      courier,
		Parcels:      append([]string(nil), moved...),
