	t.Helper()
	res, replayed, err := s.Transfer(request, fromBatch, toBatch, courier, reason, now)
	if err != nil || replayed {
		t.Fatalf("Transfer(%q) 意外失败: %v replayed=%v", request, err, replayed)
	}
	return res
}

